/**
 * Seed Data — Load from pipeline-generated data
 *
 * Instead of hardcoded mock/seed data, this module loads real data
 * from the pipeline data file generated by the portal ingestion scripts.
 *
 * If no pipeline data is available, it returns empty arrays as a safe default —
 * the engine works with whatever data the pipeline provides.
 */

import { readFileSync, existsSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

interface PipelineData {
  generatedAt: string;
  sources: Record<
    string,
    {
      status: string;
      records: number;
      data?: unknown[];
    }
  >;
  stats: Record<string, number>;
}

let _cached: PipelineData | null = null;

function loadPipelineData(): PipelineData | null {
  if (_cached) return _cached;
  try {
    const __dirname = dirname(fileURLToPath(import.meta.url));
    const dataPath = join(
      __dirname,
      "..",
      "..",
      "..",
      "portal",
      "assets",
      "pipeline-data.json",
    );
    if (!existsSync(dataPath)) return null;
    const raw = readFileSync(dataPath, "utf-8");
    _cached = JSON.parse(raw) as PipelineData;
    return _cached;
  } catch {
    return null;
  }
}

function getSeedParsedData() {
  return {
    contracts: [],
    filings: [],
    donations: [],
    disclosures: [],
    projects: [],
  };
}

export { loadPipelineData, getSeedParsedData };
export type { PipelineData };
